<template><div class="gallery"><button v-for="(item,index) in images" :key="item.image||index" @click="active=index"><img :src="item.image" alt="Vista del equipo"></button><img v-if="images.length" class="main" :src="images[active]?.image" alt="Equipo seleccionado"></div></template><script setup>import{ref}from'vue';defineProps({images:{type:Array,default:()=>[]}});const active=ref(0);</script><style scoped>.gallery{display:grid;grid-template-columns:72px 1fr;gap:.8rem}.gallery button{border:1px solid #ddd;border-radius:10px;background:#fff;padding:.2rem}.gallery button img{width:100%}.main{grid-column:2;grid-row:1/8;width:100%;height:440px;object-fit:contain;background:#fafafa;border-radius:18px}</style>
